package dev.pocket.agent;
import android.app.*;
import android.content.*;
import android.os.*;
import android.provider.Settings;
import android.text.*;
import android.text.style.*;
import android.view.*;
import android.view.accessibility.*;
import android.widget.*;
import androidx.test.platform.app.InstrumentationRegistry;
import org.json.*;
import org.junit.*;
import java.io.*;
import java.util.*;
import static org.junit.Assert.*;

/** Side-by-side QA package: never writes a user's actual provider or bot state. */
public class UnifiedBotSmokeTest {
 private android.app.Instrumentation inst;private Activity activity;private UiAutomation ui;private Context context;
 private View find(View root,String name){if(name.contentEquals(root.getContentDescription()==null?"":root.getContentDescription())||root instanceof TextView&&name.contentEquals(((TextView)root).getText()))return root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){View found=find(((ViewGroup)root).getChildAt(i),name);if(found!=null)return found;}return null;}
 private View await(String name)throws Exception{long end=System.currentTimeMillis()+20000;View[] result={null};do{inst.runOnMainSync(()->result[0]=find(activity.getWindow().getDecorView(),name));if(result[0]!=null)return result[0];Thread.sleep(100);}while(System.currentTimeMillis()<end);throw new AssertionError("Missing UI: "+name);}
 private void click(String name)throws Exception{View found=await(name);while(!found.isClickable()&&found.getParent() instanceof View)found=(View)found.getParent();View target=found;inst.runOnMainSync(target::performClick);Thread.sleep(300);}
 private void capture(String name)throws Exception{inst.waitForIdleSync();Thread.sleep(400);android.graphics.Bitmap image=ui.takeScreenshot();assertNotNull(image);try(OutputStream out=new FileOutputStream(new File(context.getFilesDir(),"unified-"+name+".png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
 private String shell(String command)throws Exception{try(ParcelFileDescriptor fd=ui.executeShellCommand(command);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(fd)){return new String(Io.bytes(in),java.nio.charset.StandardCharsets.UTF_8).trim();}}
 private JSONObject json(Object...pairs)throws Exception{JSONObject o=new JSONObject();for(int i=0;i<pairs.length;i+=2)o.put((String)pairs[i],pairs[i+1]);return o;}
 private void edits(View root,List<EditText> fields){if(root instanceof EditText)fields.add((EditText)root);if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++)edits(((ViewGroup)root).getChildAt(i),fields);}
 private AccessibilityNodeInfo node(AccessibilityNodeInfo root,String name){if(root==null)return null;if("android.widget.Button".contentEquals(root.getClassName())&&name.contentEquals(root.getText()==null?"":root.getText()))return root;for(int i=0;i<root.getChildCount();i++){AccessibilityNodeInfo found=node(root.getChild(i),name);if(found!=null)return found;}return null;}
 private void dialogEdits(AccessibilityNodeInfo root,List<AccessibilityNodeInfo> fields){if(root==null)return;if("android.widget.EditText".contentEquals(root.getClassName()))fields.add(root);for(int i=0;i<root.getChildCount();i++)dialogEdits(root.getChild(i),fields);}
 private JSONObject until(AgentApi api,String id,int count)throws Exception{long end=System.currentTimeMillis()+120000;JSONObject value=new JSONObject();do{value=api.get("/bots/"+id);JSONArray jobs=value.getJSONArray("jobs");if(jobs.length()>=count){JSONObject job=jobs.getJSONObject(count-1);if(job.optString("status").equals("failed"))fail(job.toString());if(job.optString("status").equals("completed"))return value;}Thread.sleep(150);}while(System.currentTimeMillis()<end);throw new AssertionError(value.toString());}
 private void send(String text)throws Exception{List<EditText> fields=new ArrayList<>();inst.runOnMainSync(()->edits(activity.getWindow().getDecorView(),fields));assertEquals(1,fields.size());inst.runOnMainSync(()->fields.get(0).setText(text));click("Send to bot");}
 private boolean markdown(View root){if(root instanceof TextView){CharSequence s=((TextView)root).getText();if(s instanceof Spanned&&s.toString().contains("Created")){Spanned spans=(Spanned)s;return spans.getSpans(0,s.length(),ClickableSpan.class).length>0&&spans.getSpans(0,s.length(),io.noties.markwon.core.spans.StrongEmphasisSpan.class).length>0&&!s.toString().contains("**Created**");}}if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++)if(markdown(((ViewGroup)root).getChildAt(i)))return true;return false;}
 @Test public void unifiedInboxSetupMarkdownToolsAndPhone()throws Exception{
  inst=InstrumentationRegistry.getInstrumentation();context=inst.getTargetContext();Assume.assumeTrue("Use -PqaInstall so real credentials stay untouched",context.getPackageName().endsWith(".qa"));ui=inst.getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES);if(Build.VERSION.SDK_INT>=33)ui.grantRuntimePermission(context.getPackageName(),android.Manifest.permission.POST_NOTIFICATIONS);
  context.getSharedPreferences("bot-setup",0).edit().remove("seen-v2").commit();activity=inst.startActivitySync(new Intent(context,BotsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));long ready=System.currentTimeMillis()+240000;while(!RuntimeService.ready&&System.currentTimeMillis()<ready)Thread.sleep(200);assertTrue(RuntimeService.status,RuntimeService.ready);await("Continue to bots");capture("setup");click("Continue to bots");
  AgentApi api=new AgentApi((String)new JSONTokener(Io.text(new File(context.getFilesDir(),"state/token.json"))).nextValue());assertFalse(api.get("/state").getJSONObject("settings").optBoolean("hasKey"));
  JSONArray existing=api.get("/state").getJSONArray("bots");for(int i=0;i<existing.length();i++)api.request("DELETE","/bots/"+existing.getJSONObject(i).getString("id"),null);Thread.sleep(1200);
  String original=Settings.Secure.getString(context.getContentResolver(),"enabled_accessibility_services");String botId="";
  try(BotModelFixture model=new BotModelFixture()){
   api.request("PUT","/settings",json("provider","openai","api","openai-completions","baseUrl",model.baseUrl(),"model","qa-fixture","apiKey","fixture-key"));
   click("Create bot");Thread.sleep(400);List<AccessibilityNodeInfo> fields=new ArrayList<>();dialogEdits(ui.getRootInActiveWindow(),fields);assertEquals("Creation should ask only for name and instructions",2,fields.size());for(int i=0;i<2;i++){Bundle args=new Bundle();args.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,i==0?"Everyday helper":"Help me code and use my phone");assertTrue(fields.get(i).performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,args));}capture("create");AccessibilityNodeInfo create=node(ui.getRootInActiveWindow(),"CREATE BOT");if(create==null)create=node(ui.getRootInActiveWindow(),"Create bot");assertNotNull(create);assertTrue(create.performAction(AccessibilityNodeInfo.ACTION_CLICK));
   await("Send to bot");JSONArray bots=api.get("/state").getJSONArray("bots");botId=bots.getJSONObject(0).getString("id");JSONObject bot=api.get("/bots/"+botId).getJSONObject("bot");assertEquals("unified",bot.getString("kind"));assertEquals(0,bot.getInt("dailyLimit"));assertTrue(bot.getBoolean("allowShell"));assertTrue(bot.getBoolean("allowUrgent"));Thread.sleep(1200);
   send("Create a file for me");until(api,botId,1);Thread.sleep(1200);capture("chat");boolean[] rendered={false};inst.runOnMainSync(()->rendered[0]=markdown(activity.getWindow().getDecorView()));assertTrue("Markdown styles and clickable link spans missing",rendered[0]);assertEquals("Created by my local coding bot",api.get("/file?projectId="+bot.getString("projectId")+"&path=src/bot.txt").getString("content"));capture("chat");
   click("Files");await("src");capture("files");click("src");await("bot.txt");click("Terminal");Thread.sleep(1800);String terminal=context.getSharedPreferences("bot-tools",0).getString("shell-"+bot.getString("projectId"),"");assertFalse(terminal.isEmpty());api.request("POST","/terminals/"+terminal+"/input",json("data","pwd; printf '\\nBOT_TERMINAL_OK\\n'\r"));Thread.sleep(700);assertTrue(new String(android.util.Base64.decode(api.get("/terminals/"+terminal).getString("output"),0)).contains("BOT_TERMINAL_OK"));capture("terminal");
   click("Open sidebar");click("Settings");await("Bring Your Own Key");capture("settings");assertNull(find(activity.getWindow().getDecorView(),"Mobile Use"));click("Open sidebar");capture("sidebar");click("Main terminal");Thread.sleep(1800);String rootShell=context.getSharedPreferences("bot-tools",0).getString("shell-root","");assertFalse(rootShell.isEmpty());api.request("POST","/terminals/"+rootShell+"/input",json("data","pwd; command -v git; printf '\\nMAIN_TERMINAL_OK\\n'\r"));Thread.sleep(700);String output=new String(android.util.Base64.decode(api.get("/terminals/"+rootShell).getString("output"),0));assertTrue(output.contains("/workspace"));assertTrue(output.contains("MAIN_TERMINAL_OK"));capture("main-terminal");
   shell("appops set "+context.getPackageName()+" SYSTEM_ALERT_WINDOW allow");shell("settings put secure enabled_accessibility_services "+context.getPackageName()+"/com.artemis.helper.ArtemisAccessibilityService");shell("settings put secure accessibility_enabled 1");long access=System.currentTimeMillis()+8000;while(com.artemis.helper.ArtemisAccessibilityService.getInstance()==null&&System.currentTimeMillis()<access)Thread.sleep(100);assertNotNull(com.artemis.helper.ArtemisAccessibilityService.getInstance());
   String id=botId;inst.runOnMainSync(()->context.startActivity(new Intent(context,BotsActivity.class).putExtra("botId",id).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP)));await("Send to bot");send("BROWSER_FIXTURE: open the phone browser and verify the check page");shell("input keyevent KEYCODE_HOME");until(api,botId,2);assertTrue("Bot must choose phone tools without a mode switch",model.sawUnified);assertTrue(model.sawBrowser);capture("browser");if(model.failure!=null)throw model.failure;
   context.stopService(new Intent(context,MobileOverlayService.class));inst.runOnMainSync(()->context.startActivity(new Intent(context,BotsActivity.class).putExtra("botId",id).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP)));Thread.sleep(1000);capture("completed");
  }finally{MobileAccess.authorize(false);context.stopService(new Intent(context,MobileOverlayService.class));api.request("PUT","/bots/engine",json("enabled",false));api.request("PUT","/settings",json("clearKey",true));if(original==null||original.isEmpty()||original.equals("null"))shell("settings delete secure enabled_accessibility_services");else shell("settings put secure enabled_accessibility_services "+original);}
 }
}
